using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using IndianOceanAssets.ShooterSurvival;using Object=UnityEngine.Object;
public static class CaptureSceneRoleFrames {
 static bool oldRunning;static string folder;static GameObject stage,actor;static Camera camera;static RenderTexture rt;static Animator animator;static int waitFrame,lastFrame=-1;static Queue<(string role,string state,float phase)> jobs;static List<object> rows;static Dictionary<string,GameObject> sources;
 static string Json(object o)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{o});
 public static object Main(string output){if(!EditorApplication.isPlaying)throw new Exception("Play required");oldRunning=TimeManager.isGameRunning;TimeManager.isGameRunning=true;folder=output;Directory.CreateDirectory(folder);rows=new();jobs=new();var director=Object.FindFirstObjectByType<Chapter45Director>();sources=director.encounters.SelectMany(e=>e.actors).Select(a=>a.GetComponent<Chapter45RoleAction>()).Where(b=>b!=null&&b.GetComponentsInChildren<Animator>(true).Any(a=>a.name=="Model"&&a.runtimeAnimatorController!=null&&a.runtimeAnimatorController.name.StartsWith("role-"))).GroupBy(b=>b.role.ToString()).ToDictionary(g=>g.Key,g=>g.First().gameObject);foreach(var role in sources.Keys)foreach(var state in new[]{"idle","walk","attack_once","die"})foreach(float phase in new[]{0f,.25f,.5f,.75f})jobs.Enqueue((role,state,phase));stage=new GameObject("Temporary installed role art frame review");rt=new RenderTexture(768,768,24);var cg=new GameObject("Temporary role review camera");cg.transform.SetParent(stage.transform,false);camera=cg.AddComponent<Camera>();camera.enabled=false;camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.32f,.35f,.38f);camera.orthographic=true;camera.orthographicSize=1.45f;camera.nearClipPlane=.1f;camera.farClipPlane=25;camera.targetTexture=rt;cg.transform.localPosition=new Vector3(2.9f,2.05f,5);cg.transform.LookAt(stage.transform.position+Vector3.up*1.05f);waitFrame=-1;EditorApplication.update+=Tick;return new{folder,frames=jobs.Count,pending=true};}
 static void Tick(){if(Time.frameCount==lastFrame)return;lastFrame=Time.frameCount;try{if(jobs.Count==0){Finish(null);return;}var job=jobs.Peek();if(waitFrame<0){if(actor==null||actor.name!=job.role){if(actor!=null)Object.DestroyImmediate(actor);actor=Object.Instantiate(sources[job.role],stage.transform);actor.name=job.role;actor.SetActive(false);foreach(var component in actor.GetComponentsInChildren<MonoBehaviour>(true))if(component is not Chapter45HandProps)component.enabled=false;foreach(var c in actor.GetComponentsInChildren<Collider>(true))c.enabled=false;actor.transform.localPosition=Vector3.zero;actor.transform.localRotation=Quaternion.identity;foreach(var t in actor.GetComponentsInChildren<Transform>(true))t.gameObject.layer=31;animator=actor.GetComponentInChildren<Animator>(true);animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.applyRootMotion=false;actor.SetActive(true);animator.enabled=true;animator.speed=0;foreach(var r in animator.GetComponentsInChildren<Renderer>(true))r.enabled=true;}animator.enabled=true;animator.Play(job.state,0,job.phase);animator.Update(0);animator.enabled=false;foreach(var p in actor.GetComponentsInChildren<Chapter45HandProps>())p.ApplyPose();waitFrame=Time.frameCount+3;return;}foreach(var p in actor.GetComponentsInChildren<Chapter45HandProps>())p.ApplyPose();if(Time.frameCount<waitFrame)return;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var png=new Texture2D(768,768,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,768,768),0,0);png.Apply();string file=job.role+"-"+job.state+"-"+job.phase.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+".png";File.WriteAllBytes(Path.Combine(folder,file),png.EncodeToPNG());Object.DestroyImmediate(png);RenderTexture.active=old;rows.Add(new{job.role,job.state,job.phase,file,frame=Time.frameCount,controller=animator.runtimeAnimatorController.name});jobs.Dequeue();waitFrame=-1;}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string error){EditorApplication.update-=Tick;TimeManager.isGameRunning=oldRunning;if(stage!=null)Object.DestroyImmediate(stage);if(rt!=null){rt.Release();Object.DestroyImmediate(rt);}File.WriteAllText(Path.Combine(folder,"result.json"),Json(new{completed=error==null,error,frames=rows,conditions="Actual Unity Play; clones of installed scene actors including own controller and hand attachments; wait three actual frames. Isolated art fixture, not ordinary gameplay."}));}
}
